const pair = $('Loop Over Candidate Pairs').all(1, $runIndex)[0]?.json?.pair;
const config = $('Set: Reconciliation Configuration').first().json;
const candidate = $json.output ?? $json.text ?? $json;
let classification = candidate;
if (typeof classification === 'string') {
  try { classification = JSON.parse(classification); } catch { throw new Error('Identity classifier did not return valid JSON'); }
}

const fail = (message) => { throw new Error(`Unsafe identity classification: ${message}`); };
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
if (!isObject(pair) || !isObject(pair.left) || !isObject(pair.right)) fail('candidate pair is missing');
for (const side of ['left', 'right']) {
  const record = pair[side];
  for (const field of ['event_id', 'public_id', 'slug', 'fingerprint', 'incident_date', 'evidence']) {
    if (typeof record[field] !== 'string' || record[field].length === 0) fail(`${side}.${field} is missing`);
  }
}
if (!isObject(classification)) fail('result is not an object');
const required = ['relation', 'confidence', 'same_actor', 'same_action', 'same_occurrence', 'material_followup', 'evidence_left', 'evidence_right', 'rationale'];
const keys = Object.keys(classification);
if (keys.length !== required.length || required.some((key) => !keys.includes(key))) fail('result fields do not match the contract');
if (!['same_event', 'different_event', 'uncertain'].includes(classification.relation)) fail('relation is invalid');
if (typeof classification.confidence !== 'number' || !Number.isFinite(classification.confidence) || classification.confidence < 0 || classification.confidence > 1) fail('confidence is outside 0..1');
for (const field of ['same_actor', 'same_action', 'same_occurrence', 'material_followup']) {
  if (typeof classification[field] !== 'boolean') fail(`${field} must be boolean`);
}
const bounded = (value, min, max) => typeof value === 'string' && value.length >= min && value.length <= max;
if (!bounded(classification.evidence_left, 24, 500) || !pair.left.evidence.includes(classification.evidence_left)) fail('left evidence is not a verbatim excerpt');
if (!bounded(classification.evidence_right, 24, 500) || !pair.right.evidence.includes(classification.evidence_right)) fail('right evidence is not a verbatim excerpt');
if (!bounded(classification.rationale, 12, 1000)) fail('rationale length is invalid');

return { json: {
  pair,
  classification,
  context: {
    execution_id: String($execution.id),
    model: String(config.model),
    prompt_version: String(config.prompt_version),
    auto_merge: config.auto_merge === true,
  },
} };
